// Regression fixture + WASM-vs-JS narrow-phase differential for the
// Architecture/MEP office fixture pair (tests/fixtures/office-architecture.ifc
// + office-mep.ifc, generated by tests/fixtures/generate-office-ifc.js).
//
// Harness pattern (server + offline-deps CDN routing) copied from
// tests/browser/smoke.mjs / wasm-sweep-differential.mjs — see those files
// for the offline-mirror rationale. This does NOT import from /tmp.
//
// Three things asserted, in one browser session so both engines see the
// SAME loaded geometry:
//   1. A default-rules HARD clash run with the WASM narrow phase available
//      finds an EXACT, pinned count (re-measured against this fixture, not
//      guessed — see the assertion below for how to re-measure after an
//      intentional geometry/rule change).
//   2. The same run with every WASM narrow-phase global removed
//      (_ccWasmIntersect/_ccWasmMinDist/_ccWasmBatchIntersect — forcing the
//      JS BVH+Moller fallback) finds the IDENTICAL clash set (order-
//      independent, by element-pair identity), not just the same count.
//   3. A soft/clearance run at 100mm finds the device-under-slab proximity
//      the fixture generator adds specifically for this (see
//      generate-office-ifc.js's "Sensor device" comment) — both engines
//      agree on it too.
//
// Run:  CC_CHROMIUM_EXECUTABLE=... CC_BROWSER_OFFLINE_DEPS=1 \
//       node tests/browser/office-clash-parity.mjs
import { createServer } from 'node:http';
import { readFile } from 'node:fs/promises';
import { extname, join, normalize } from 'node:path';
import { fileURLToPath } from 'node:url';
import { chromium } from 'playwright';

const root = fileURLToPath(new URL('../..', import.meta.url));
const MIME = {
  '.html': 'text/html', '.js': 'text/javascript', '.mjs': 'text/javascript',
  '.json': 'application/json', '.wasm': 'application/wasm', '.png': 'image/png',
  '.svg': 'image/svg+xml', '.ifc': 'application/octet-stream', '.css': 'text/css',
};

let allOk = true;
function fail(msg) { console.error('OFFICE PARITY FAIL: ' + msg); allOk = false; }

const server = createServer(async (req, res) => {
  try {
    const urlPath = decodeURIComponent(new URL(req.url, 'http://x').pathname);
    const rel = urlPath === '/' ? 'index.html' : urlPath.slice(1);
    const file = normalize(join(root, rel));
    if (!file.startsWith(normalize(root))) { res.writeHead(403); return res.end(); }
    const body = await readFile(file);
    res.writeHead(200, { 'Content-Type': MIME[extname(file)] || 'application/octet-stream' });
    res.end(body);
  } catch {
    res.writeHead(404); res.end();
  }
});
await new Promise((r) => server.listen(0, '127.0.0.1', r));
const port = server.address().port;

// No --single-process/--no-zygote here (unlike smoke.mjs, which only ever
// opens one page): this test opens several pages sequentially from one
// browser instance (like wasm-sweep-differential.mjs), and single-process
// mode was observed to crash the whole browser on the second page.
const localChromium = process.env.CC_CHROMIUM_EXECUTABLE;
const browser = await chromium.launch({ executablePath: localChromium });
const errors = [];

async function newPage() {
  const page = await browser.newPage();
  page.on('pageerror', (e) => errors.push('pageerror: ' + e.message));
  page.on('console', (m) => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
  if (process.env.CC_BROWSER_OFFLINE_DEPS === '1') {
    async function local(route, file, contentType) {
      await route.fulfill({
        status: 200,
        body: await readFile(join(root, 'node_modules', file)),
        headers: { 'content-type': contentType || 'text/javascript', 'access-control-allow-origin': '*' },
      });
    }
    await page.context().route('https://cdnjs.cloudflare.com/ajax/libs/react/18.2.0/umd/react.production.min.js', (r) => local(r, 'react/umd/react.production.min.js'));
    await page.context().route('https://cdnjs.cloudflare.com/ajax/libs/react-dom/18.2.0/umd/react-dom.production.min.js', (r) => local(r, 'react-dom/umd/react-dom.production.min.js'));
    await page.context().route('https://cdnjs.cloudflare.com/ajax/libs/jszip/3.10.1/jszip.min.js', (r) => local(r, 'jszip/dist/jszip.min.js'));
    await page.context().route('https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js', (r) => local(r, 'pdfjs-dist/build/pdf.min.js'));
    await page.context().route('https://cdn.jsdelivr.net/npm/three@0.180.0/**', async (route) => {
      const suffix = new URL(route.request().url()).pathname.split('/three@0.180.0/')[1];
      await local(route, 'three/' + suffix);
    });
    await page.context().route('https://cdn.jsdelivr.net/npm/web-ifc@0.0.77/**', async (route) => {
      const suffix = new URL(route.request().url()).pathname.split('/web-ifc@0.0.77/')[1];
      await local(route, 'web-ifc/' + suffix, suffix.endsWith('.wasm') ? 'application/wasm' : 'text/javascript');
    });
    await page.context().route('https://fonts.googleapis.com/**', (route) => route.fulfill({ status: 200, body: '', contentType: 'text/css' }));
    await page.context().route('https://fonts.gstatic.com/**', (route) => route.abort());
    await page.context().route('https://gc.zgo.at/**', (route) => route.fulfill({ status: 200, body: '', contentType: 'text/javascript' }));
  }
  await page.goto(`http://127.0.0.1:${port}/`, { waitUntil: 'domcontentloaded' });
  await page.waitForFunction(() => window.ClashControl && typeof window._ccDispatch === 'function', null, { timeout: 60_000 });
  return page;
}

async function loadFixtures(page) {
  await page.evaluate(async () => {
    const [archBuf, mepBuf] = await Promise.all([
      fetch('/tests/fixtures/office-architecture.ifc').then((r) => r.arrayBuffer()),
      fetch('/tests/fixtures/office-mep.ifc').then((r) => r.arrayBuffer()),
    ]);
    const files = [
      new File([archBuf], 'office-architecture.ifc'),
      new File([mepBuf], 'office-mep.ifc'),
    ];
    // The real file-input path: window.ClashControl.loadFiles is exactly
    // what the app's <input type="file"> handler calls with the FileList
    // it receives — there is no separate "test-only" load API.
    window.ClashControl.loadFiles(files);
  });
  await page.waitForFunction(() => {
    const s = window._ccLatestState;
    return s && s.models.length === 2 && s.models.every((m) => (m.elements || []).length > 0) && window._ccModelLoading === false;
  }, null, { timeout: 120_000 });
}

async function runDetectionInPage(page, rulesOverride, disableWasmNarrowPhase) {
  return page.evaluate(async ({ rules, disableWasm }) => {
    let saved = null;
    if (disableWasm) {
      saved = {
        intersect: window._ccWasmIntersect, minDist: window._ccWasmMinDist, batch: window._ccWasmBatchIntersect,
      };
      delete window._ccWasmIntersect; delete window._ccWasmMinDist; delete window._ccWasmBatchIntersect;
    }
    let result;
    try {
      result = await window.ClashControl.runDetection(rules);
    } finally {
      if (disableWasm && saved) {
        if (saved.intersect) window._ccWasmIntersect = saved.intersect;
        if (saved.minDist) window._ccWasmMinDist = saved.minDist;
        if (saved.batch) window._ccWasmBatchIntersect = saved.batch;
      }
    }
    return (result || []).map((c) => {
      const a = c.eA ? c.eA.expressId : (c.elA && c.elA.expressId);
      const b = c.eB ? c.eB.expressId : (c.elB && c.elB.expressId);
      const ids = [a, b].sort((x, y) => x - y);
      return { key: ids[0] + ':' + ids[1] + ':' + c.type + ':' + (c.sameModel ? 1 : 0), type: c.type, clearanceMm: c.clearanceMm };
    });
  }, { rules: rulesOverride, disableWasm: disableWasmNarrowPhase });
}

try {
  // ── Case 1+2: default hard-clash rules, WASM vs JS narrow phase ──
  const page1 = await newPage();
  await loadFixtures(page1);
  await page1.waitForFunction(() => typeof window._ccWasmIntersect === 'function', null, { timeout: 30_000 })
    .catch(() => fail('WASM narrow-phase engine never became ready — parity run would be JS-vs-JS, not a real differential'));

  // hard:true + maxGap:0 is required to get a HARD-ONLY result set — with
  // maxGap>0 the engine also emits soft clashes up to that gap alongside
  // the hard ones (see index.html's `_wantsSoft` doc comment), which would
  // contaminate the pinned hard-only count below.
  const wasmRules = { hard: true, maxGap: 0, excludeSameDiscipline: false, selfClashModels: 'none' };
  const wasmHard = await runDetectionInPage(page1, wasmRules, false);
  const jsHard = await runDetectionInPage(page1, wasmRules, true);
  await page1.close();

  const wasmKeys = wasmHard.map((c) => c.key).sort();
  const jsKeys = jsHard.map((c) => c.key).sort();
  if (JSON.stringify(wasmKeys) !== JSON.stringify(jsKeys)) {
    console.error('WASM keys:', wasmKeys);
    console.error('JS keys:  ', jsKeys);
    fail('WASM and JS narrow phase found DIFFERENT hard-clash sets (wasm=' + wasmHard.length + ', js=' + jsHard.length + ')');
  } else {
    console.log('PARITY OK — WASM and JS narrow phase agree on the hard-clash set (' + wasmHard.length + ' clashes)');
  }

  // Known-count regression lock. Re-measure with:
  //   CC_CHROMIUM_EXECUTABLE=... CC_BROWSER_OFFLINE_DEPS=1 node tests/browser/office-clash-parity.mjs
  // and read the "agree on the hard-clash set (N clashes)" line above —
  // update EXPECTED_HARD_COUNT to N only after confirming the new number is
  // geometrically correct (e.g. an intentional fixture or rule change), not
  // just "the assertion failed so I copied the new number in".
  const EXPECTED_HARD_COUNT = 56;
  if (wasmHard.length !== EXPECTED_HARD_COUNT) {
    fail('expected exactly ' + EXPECTED_HARD_COUNT + ' hard clashes with default rules, got ' + wasmHard.length);
  } else {
    console.log('COUNT OK — exactly ' + EXPECTED_HARD_COUNT + ' hard clashes, as pinned');
  }

  // ── Case 3: soft/clearance run at 100mm, WASM vs JS, device/slab found ──
  const page2 = await newPage();
  await loadFixtures(page2);
  await page2.waitForFunction(() => typeof window._ccWasmMinDist === 'function', null, { timeout: 30_000 })
    .catch(() => fail('WASM narrow-phase engine never became ready for the soft-clearance run'));

  const softRules = { excludeSameDiscipline: false, selfClashModels: 'none', hard: false, minGap: 0, maxGap: 100 };
  const wasmSoft = await runDetectionInPage(page2, softRules, false);
  const jsSoft = await runDetectionInPage(page2, softRules, true);
  await page2.close();

  const wasmSoftKeys = wasmSoft.map((c) => c.key).sort();
  const jsSoftKeys = jsSoft.map((c) => c.key).sort();
  if (JSON.stringify(wasmSoftKeys) !== JSON.stringify(jsSoftKeys)) {
    fail('WASM and JS narrow phase found DIFFERENT soft-clearance sets at 100mm (wasm=' + wasmSoft.length + ', js=' + jsSoft.length + ')');
  } else {
    console.log('PARITY OK — WASM and JS narrow phase agree on the 100mm soft-clearance set (' + wasmSoft.length + ' clashes)');
  }
  // The fixture's "Sensor device" sits exactly 0.1m under its storey's
  // floor slab, mid-face (not near any slab vertex) — the specific
  // regression this whole test exists to catch (see the fixture generator's
  // doc comment). A 100mm run MUST find it on both engines.
  const deviceHit = wasmSoft.some((c) => c.type === 'soft' && typeof c.clearanceMm === 'number' && c.clearanceMm <= 100);
  if (!deviceHit) {
    fail('100mm soft-clearance run did not find the device-under-slab proximity the fixture adds for this (this is exactly the vertex-to-vertex bug this fixture regression-tests)');
  } else {
    console.log('DEVICE/SLAB OK — the mid-face device-to-slab clearance was found by the true point-to-triangle min-distance kernel');
  }

  if (errors.length) fail('browser emitted uncaught page or console errors: ' + JSON.stringify(errors.slice(0, 10)));
} finally {
  await browser.close();
  server.close();
}
if (!allOk) process.exit(1);
